// NOTE: originally auto-generated by Lovable; hand-maintained since — see the
// "realtime.transport: ws" addition below, needed because @supabase/supabase-js
// always constructs a Realtime client internally (even though nothing here
// uses realtime), and that construction throws if it can't find a WebSocket
// implementation on the server. Passing the "ws" package explicitly avoids
// depending on which Node.js version Vercel actually runs this function under.
import { createMiddleware } from '@tanstack/react-start'
import { getRequest } from '@tanstack/react-start/server'
import { createClient } from '@supabase/supabase-js'
import ws from 'ws'
import type { Database } from './types'



export const requireSupabaseAuth = createMiddleware({ type: 'function' }).server(
  async ({ next }) => {
    
    const SUPABASE_URL = process.env.SUPABASE_URL;
    const SUPABASE_PUBLISHABLE_KEY = process.env.SUPABASE_PUBLISHABLE_KEY;

    if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
      const missing = [
        ...(!SUPABASE_URL ? ['SUPABASE_URL'] : []),
        ...(!SUPABASE_PUBLISHABLE_KEY ? ['SUPABASE_PUBLISHABLE_KEY'] : []),
      ];
      const message = `Missing Supabase environment variable(s): ${missing.join(', ')}. Connect Supabase in Lovable Cloud.`;
      console.error(`[Supabase] ${message}`);
      throw new Response(message, { status: 500 });
    }
    
    // SEC-01 defense in depth: never use a mismatched Supabase endpoint.
    // The isolated Preview has a branch-scoped project ID and URL.
    const expectedProject = process.env.VITE_SUPABASE_PROJECT_ID;
    if (expectedProject) {
      let host: string;
      try {
        host = new URL(SUPABASE_URL).hostname;
      } catch {
        throw new Response('Invalid Supabase endpoint', { status: 500 });
      }
      if (host !== `${expectedProject}.supabase.co`) {
        throw new Response('Supabase project mismatch', { status: 500 });
      }
    }

    const request = getRequest();

    if (!request?.headers) {
      throw new Response('Unauthorized: No request headers available', { status: 401 });
    }

    const authHeader = request.headers.get('authorization');

    if (!authHeader) {
      throw new Response('Unauthorized: No authorization header provided', { status: 401 });
    }

    if (!authHeader.startsWith('Bearer ')) {
      throw new Response('Unauthorized: Only Bearer tokens are supported', { status: 401 });
    }

    const token = authHeader.replace('Bearer ', '');
    if (!token) {
      throw new Response('Unauthorized: No token provided', { status: 401 });
    }

    const supabase = createClient<Database>(
      SUPABASE_URL!,
      SUPABASE_PUBLISHABLE_KEY!,
      {
        global: {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
        auth: {
          storage: undefined,
          persistSession: false,
          autoRefreshToken: false,
        },
        realtime: {
          transport: ws as any,
        },
      }
    );

    const { data, error } = await supabase.auth.getClaims(token);
    if (error || !data?.claims) {
      throw new Response('Unauthorized: Invalid token', { status: 401 });
    }

    if (!data.claims.sub) {
      throw new Response('Unauthorized: No user ID found in token', { status: 401 });
    }

    // SEC-03: a valid JWT is not sufficient for CRM access.
    // Query with the caller-bound client; fail closed on missing or inactive profiles.
    const { data: profile, error: profileError } = await supabase
      .from('profiles')
      .select('status, is_active')
      .eq('id', data.claims.sub)
      .maybeSingle();

    if (profileError || !profile || profile.status !== 'approved' || profile.is_active !== true) {
      throw new Response('Forbidden: CRM account is not approved and active', { status: 403 });
    }

    return next({
      context: {
        supabase,
        userId: data.claims.sub,
        claims: data.claims,
      },
    })
  }
)